// SockJS 客户端实现 - 支持SockJS协议协商
// 后端配置了.withSockJS()，需要先请求/info端点进行协议协商
window.SockJS = function(url) {
    const self = this;
    this.readyState = 0; // CONNECTING
    this.ws = null;
    
    // 提取基础URL和查询参数
    const urlParts = url.split('?');
    const baseUrl = urlParts[0];
    const query = urlParts.length > 1 ? '?' + urlParts[1] : '';
    
    // 构建完整URL
    let fullUrl;
    if (baseUrl.startsWith('/')) {
        // 相对路径
        const protocol = window.location.protocol;
        const host = window.location.host;
        fullUrl = protocol + '//' + host + baseUrl;
    } else {
        fullUrl = baseUrl;
    }
    
    // 先请求SockJS的/info端点进行协议协商
    const infoUrl = fullUrl + '/info' + query;
    
    fetch(infoUrl, {
        method: 'GET',
        headers: {
            'Accept': 'application/json'
        }
    })
    .then(response => {
        if (!response.ok) {
            throw new Error('SockJS info request failed: ' + response.status);
        }
        return response.json();
    })
    .then(info => {
        // 从info中获取WebSocket URL
        // SockJS协议：如果支持WebSocket，使用/websocket路径
        const wsProtocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
        const wsHost = window.location.host;
        const wsPath = baseUrl + '/websocket' + query;
        const wsUrl = wsProtocol + '//' + wsHost + wsPath;
        
        // 建立WebSocket连接
        self.ws = new WebSocket(wsUrl);
        self.readyState = self.ws.readyState;
        
        self.ws.onopen = function(e) {
            self.readyState = 1; // OPEN
            if (self.onopen) self.onopen(e);
        };
        
        self.ws.onmessage = function(e) {
            if (self.onmessage) self.onmessage(e);
        };
        
        self.ws.onclose = function(e) {
            self.readyState = 3; // CLOSED
            if (self.onclose) self.onclose(e);
        };
        
        self.ws.onerror = function(e) {
            if (self.onerror) self.onerror(e);
        };
    })
    .catch(error => {
        console.error('SockJS连接失败，尝试直接使用WebSocket:', error);
        // 如果SockJS协议失败，尝试直接使用WebSocket（降级方案）
        const wsProtocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
        const wsHost = window.location.host;
        const wsUrl = wsProtocol + '//' + wsHost + baseUrl + query;
        
        try {
            self.ws = new WebSocket(wsUrl);
            self.readyState = self.ws.readyState;
            
            self.ws.onopen = function(e) {
                self.readyState = 1;
                if (self.onopen) self.onopen(e);
            };
            
            self.ws.onmessage = function(e) {
                if (self.onmessage) self.onmessage(e);
            };
            
            self.ws.onclose = function(e) {
                self.readyState = 3;
                if (self.onclose) self.onclose(e);
            };
            
            self.ws.onerror = function(e) {
                if (self.onerror) self.onerror(e);
            };
        } catch (wsError) {
            console.error('WebSocket连接也失败:', wsError);
            self.readyState = 3;
            if (self.onerror) {
                self.onerror(wsError);
            }
        }
    });
    
    this.send = function(data) {
        if (this.ws && this.ws.readyState === 1) {
            this.ws.send(data);
        } else {
            console.warn('WebSocket未连接，无法发送数据');
        }
    };
    
    this.close = function() {
        if (this.ws) {
            this.ws.close();
        }
    };
};